    if not helper_class:
        return Response("Unsupported OAuth provider", HTTP_400_BAD_REQUEST)

    helper = helper_class(code, redirect_uri)
    session_id = helper.complete_login()  # Create a new session for the user
    user_info = helper.get_user_info()
